/**
 * Parametric house kit for a builder-configurator page.
 *
 * buildHouse() returns a THREE.Group whose meshes are named so callers
 * (and tests) can address individual parts:
 *
 *   - `floor-${i}`   stacked wall boxes, one per floor (i = 0..floors-1)
 *   - `roof`         either a gable (custom triangular-prism BufferGeometry)
 *                    or a flat slab, depending on the `roof` option
 *   - `facade`       thin slab covering the building's full front face;
 *                    all windows live within this slab's bounds
 *   - `door`         door on the front face of floor 0, bottom at y = 0
 *   - `window`       one mesh per window, `windowsPerFloor` per floor,
 *                    spaced evenly across the front
 *
 * Height rules (documented for tests):
 *   - Gable roof:  total height = floors * floorHeight + roofHeight(depth)
 *   - Flat roof:   total height = floors * floorHeight + FLAT_ROOF_SLAB_THICKNESS
 *   - Difference between the two = roofHeight(depth) - FLAT_ROOF_SLAB_THICKNESS
 *
 * Window skip rule (documented for tests):
 *   The front face is divided into windowsPerFloor equal columns. A column is
 *   SKIPPED when its evenly-spaced window box would overlap the door's
 *   x-range on the front of floor 0 (|centerX| < DOOR_WIDTH/2 + windowWidth/2).
 *   With the defaults (width=8, windowsPerFloor=3) exactly one column — the
 *   middle one — overlaps the door, so the default count is
 *   floors * windowsPerFloor - 1 = 5.
 */

import * as THREE from "three";

export const DEFAULTS = Object.freeze({
  floors: 2,
  floorHeight: 3,
  width: 8,
  depth: 6,
  roof: "gable",
  windowsPerFloor: 3,
});

export const DOOR_WIDTH = 1.0;
export const DOOR_HEIGHT = 2.2;

export const WINDOW_HEIGHT = 1.2;

/** Thickness of the flat-roof slab. */
export const FLAT_ROOF_SLAB_THICKNESS = 0.3;

/**
 * Height added by the gable roof on top of the topmost floor.
 * @param {number} [depth] house depth; ridge height scales with it
 * @returns {number} gable roof height
 */
export function roofHeight(depth = DEFAULTS.depth) {
  return depth * 0.5;
}

/**
 * Build a custom triangular-prism gable roof geometry.
 * Cross-section is a triangle in the x/y plane (ridge running along z):
 * (-w/2,0) -> (w/2,0) -> (0,h), extruded from z=-d/2 to z=+d/2.
 */
function createGableGeometry(width, height, depth) {
  const hw = width / 2;
  const hd = depth / 2;

  //        C(0,h,-hd)      F(0,h,+hd)
  //       / \             / \
  //  A(-hw,0,-hd)---B(hw,0,-hd)---E(hw,0,+hd)---D(-hw,0,+hd)
  const positions = new Float32Array([
    // A          B           C
    -hw, 0, -hd, hw, 0, -hd, 0, height, -hd,
    // D          E           F
    -hw, 0, hd, hw, 0, hd, 0, height, hd,
  ]);

  // Wound CCW as seen from outside each face.
  const indices = [
    0, 2, 1, // front triangle (normal -z): A, C, B
    3, 4, 5, // back triangle  (normal +z): D, E, F
    0, 3, 5, 0, 5, 2, // left slope: A,D,F / A,F,C
    1, 5, 4, 1, 2, 5, // right slope: B,F,E / B,C,E
    0, 1, 4, 0, 4, 3, // bottom: A,B,E / A,E,D
  ];

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute("position", new THREE.BufferAttribute(positions, 3));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return geometry;
}

/**
 * Build the parametric house.
 *
 * @param {object} [options]
 * @param {number} [options.floors=2]            number of stacked floor boxes
 * @param {number} [options.floorHeight=3]       height of each floor
 * @param {number} [options.width=8]             house width along x
 * @param {number} [options.depth=6]             house depth along z (front at +z)
 * @param {"gable"|"flat"} [options.roof="gable"] roof style
 * @param {number} [options.windowsPerFloor=3]   windows per floor across the front
 * @returns {THREE.Group} named meshes: floor-<i>, roof, facade, door, window*
 */
export function buildHouse({
  floors = DEFAULTS.floors,
  floorHeight = DEFAULTS.floorHeight,
  width = DEFAULTS.width,
  depth = DEFAULTS.depth,
  roof = DEFAULTS.roof,
  windowsPerFloor = DEFAULTS.windowsPerFloor,
} = {}) {
  if (floors < 1) throw new RangeError("floors must be >= 1");
  if (floorHeight <= 0) throw new RangeError("floorHeight must be > 0");
  if (width <= 0 || depth <= 0) throw new RangeError("width/depth must be > 0");
  if (!Number.isInteger(windowsPerFloor) || windowsPerFloor < 1) {
    throw new RangeError("windowsPerFloor must be an integer >= 1");
  }
  if (roof !== "gable" && roof !== "flat") {
    throw new TypeError('roof must be "gable" or "flat"');
  }

  const group = new THREE.Group();

  const wallMaterial = new THREE.MeshStandardMaterial({ color: 0xe8dcc8 });
  const roofMaterial = new THREE.MeshStandardMaterial({ color: 0x8b3a2f });
  const facadeMaterial = new THREE.MeshStandardMaterial({ color: 0xf2ead9 });
  const doorMaterial = new THREE.MeshStandardMaterial({ color: 0x5b3a29 });
  const windowMaterial = new THREE.MeshStandardMaterial({
    color: 0x9fd4e8,
    metalness: 0.1,
    roughness: 0.25,
  });

  // --- Stacked floor boxes -------------------------------------------------
  const wallsHeight = floors * floorHeight;
  for (let i = 0; i < floors; i++) {
    const floorMesh = new THREE.Mesh(
      new THREE.BoxGeometry(width, floorHeight, depth),
      wallMaterial
    );
    floorMesh.name = `floor-${i}`;
    floorMesh.position.y = i * floorHeight + floorHeight / 2;
    group.add(floorMesh);
  }

  // --- Roof -----------------------------------------------------------------
  let roofMesh;
  if (roof === "gable") {
    const rh = roofHeight(depth);
    roofMesh = new THREE.Mesh(createGableGeometry(width, rh, depth), roofMaterial);
    roofMesh.position.y = wallsHeight; // prism base sits on the top floor
  } else {
    // Flat slab with a small overhang on all sides.
    const overhang = 0.3;
    roofMesh = new THREE.Mesh(
      new THREE.BoxGeometry(
        width + 2 * overhang,
        FLAT_ROOF_SLAB_THICKNESS,
        depth + 2 * overhang
      ),
      roofMaterial
    );
    roofMesh.position.y = wallsHeight + FLAT_ROOF_SLAB_THICKNESS / 2;
  }
  roofMesh.name = "roof";
  group.add(roofMesh);

  // --- Front-face facade slab ----------------------------------------------
  // Thin slab spanning the entire front face (z = +depth side); all windows
  // are placed strictly inside its bounds.
  const facadeDepth = 0.1;
  const facade = new THREE.Mesh(
    new THREE.BoxGeometry(width, wallsHeight, facadeDepth),
    facadeMaterial
  );
  facade.name = "facade";
  facade.position.set(0, wallsHeight / 2, depth / 2 - facadeDepth / 2);
  group.add(facade);

  // --- Door on the front face of floor 0 -----------------------------------
  const doorDepth = 0.15;
  const door = new THREE.Mesh(
    new THREE.BoxGeometry(DOOR_WIDTH, DOOR_HEIGHT, doorDepth),
    doorMaterial
  );
  door.name = "door";
  // Center at DOOR_HEIGHT/2 so the bottom sits exactly at y = 0.
  door.position.set(0, DOOR_HEIGHT / 2, depth / 2 - doorDepth / 2);
  group.add(door);

  // --- Windows, evenly spaced per floor, skipping the door column ----------
  const columnWidth = width / windowsPerFloor;
  const windowWidth = Math.min(1.2, columnWidth * 0.6);
  const winH = Math.min(WINDOW_HEIGHT, floorHeight * 0.4);
  const windowDepth = 0.06;
  const windowZ = depth / 2 - facadeDepth - windowDepth / 2; // strictly inside facade

  for (let f = 0; f < floors; f++) {
    for (let i = 0; i < windowsPerFloor; i++) {
      const centerX = -width / 2 + (i + 0.5) * columnWidth;
      // Skip any column whose window box would intersect the door's x-range.
      if (Math.abs(centerX) < DOOR_WIDTH / 2 + windowWidth / 2) continue;

      const win = new THREE.Mesh(
        new THREE.BoxGeometry(windowWidth, winH, windowDepth),
        windowMaterial
      );
      win.name = "window";
      win.position.set(centerX, f * floorHeight + floorHeight / 2, windowZ);
      group.add(win);
    }
  }

  group.userData.roofStyle = roof;
  group.userData.roofHeight = roof === "gable" ? roofHeight(depth) : FLAT_ROOF_SLAB_THICKNESS;
  return group;
}

