import { describe, it, expect } from "vitest";
import * as THREE from "three";
import {
  buildHouse,
  roofHeight,
  FLAT_ROOF_SLAB_THICKNESS,
} from "../src/house.js";

const boxOf = (obj) => new THREE.Box3().setFromObject(obj);

describe("house kit", () => {
  it("gable total height equals floors*floorHeight + roofHeight within 1e-6", () => {
    const opts = { floors: 2, floorHeight: 3, depth: 6 };
    const house = buildHouse(opts);
    const box = boxOf(house);
    const expected = opts.floors * opts.floorHeight + roofHeight(opts.depth);
    expect(Math.abs(box.max.y - box.min.y - expected)).toBeLessThanOrEqual(1e-6);
    // Also holds for non-default dimensions.
    const alt = buildHouse({ floors: 3, floorHeight: 2.5, depth: 5 });
    const altBox = boxOf(alt);
    const altExpected = 3 * 2.5 + roofHeight(5);
    expect(Math.abs(altBox.max.y - altBox.min.y - altExpected)).toBeLessThanOrEqual(1e-6);
  });

  it('switching roof to "flat" reduces Box3 height by roofHeight(depth) - FLAT_ROOF_SLAB_THICKNESS', () => {
    // Documented difference: the gable adds roofHeight(depth) on top of the
    // walls, while the flat roof adds only FLAT_ROOF_SLAB_THICKNESS.
    const opts = { floors: 2, floorHeight: 3, depth: 6 };
    const gable = boxOf(buildHouse({ ...opts, roof: "gable" }));
    const flat = boxOf(buildHouse({ ...opts, roof: "flat" }));
    const documentedDifference = roofHeight(opts.depth) - FLAT_ROOF_SLAB_THICKNESS;
    expect(gable.max.y - gable.min.y - (flat.max.y - flat.min.y)).toBeCloseTo(
      documentedDifference,
      6
    );
    // Flat total height itself follows its own rule.
    const flatExpected = opts.floors * opts.floorHeight + FLAT_ROOF_SLAB_THICKNESS;
    expect(Math.abs(flat.max.y - flat.min.y - flatExpected)).toBeLessThanOrEqual(1e-6);
  });

  it("window count equals floors*windowsPerFloor minus skipped door column(s)", () => {
    /**
     * Skip rule (documented in src/house.js): the front face is divided into
     * windowsPerFloor equal columns; a column is skipped when its window box
     * would overlap the door's x-range. With the defaults (width=8,
     * windowsPerFloor=3) exactly ONE column — the middle one — overlaps the
     * door, so per floor 3 - 1 = 2 windows remain:
     *   default expected = floors*windowsPerFloor - skippedPerFloor
     *                    = 2 * 3 - 1 = 5.
     */
    const house = buildHouse(); // defaults: floors=2, windowsPerFloor=3
    let count = 0;
    house.traverse((o) => {
      if (o.name === "window") count++;
    });
    expect(count).toBe(5); // exact number for the default configuration

    // No window may intersect the door's x-range on floor 0.
    const depth = 6;
    const doorXMin = -0.5;
    const doorXMax = 0.5;
    house.traverse((o) => {
      if (o.name !== "window") return;
      const b = boxOf(o);
      const intersectsDoorColumn =
        b.min.x < doorXMax && b.max.x > doorXMin && b.min.y < 3 && b.max.y > 0;
      expect(intersectsDoorColumn).toBe(false);
    });

    // Sanity check of the rule on another configuration (no skip possible:
    // even number of columns straddles the center without overlapping it).
    const wide = buildHouse({ floors: 1, width: 10, windowsPerFloor: 4 });
    let wideCount = 0;
    wide.traverse((o) => {
      if (o.name === "window") wideCount++;
    });
    expect(wideCount).toBe(4);
  });

  it("every window's Box3 is contained in the front-face facade slab", () => {
    const house = buildHouse();
    const facade = house.getObjectByName("facade");
    expect(facade).toBeDefined();
    const facadeBox = boxOf(facade);

    let checked = 0;
    house.traverse((o) => {
      if (o.name !== "window") return;
      const winBox = boxOf(o);
      expect(
        facadeBox.containsBox(winBox),
        `window at ${o.position.toArray()} escapes the facade slab`
      ).toBe(true);
      checked++;
    });
    expect(checked).toBeGreaterThan(0);
  });

  it("door bottom sits at y = 0 within 1e-9", () => {
    const house = buildHouse();
    const door = house.getObjectByName("door");
    expect(door).toBeDefined();
    const doorBox = boxOf(door);
    expect(Math.abs(doorBox.min.y)).toBeLessThanOrEqual(1e-9);
  });
});

